const searchQuery = typeof query !== 'undefined' ? query : (typeof input !== 'undefined' ? input : '');
const apiKey = "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";
try {
